    print(f"Reason: {reason}")

import os
import re
import math
import subprocess
import sys


def get_output_text():
    """Try to get output from various sources."""
    output_text = None

    # Check for stdout capture
    for stdout_file in ["pred_results/stdout.txt", "stdout.txt", "pred_results/output.txt"]:
        if os.path.exists(stdout_file):
            with open(stdout_file, 'r') as <local-path>                content = f.read()
                if content.strip():
                    return content

    # Check for any output files in pred_results
    pred_dir = "pred_results"
    if os.path.exists(pred_dir):
        for f in os.listdir(pred_dir):
            fpath = os.path.join(pred_dir, f)
            if os.path.isfile(fpath) and not f.endswith('.py'):
                try:
                    with open(fpath, 'r') as fp:
                        content = fp.read()
                        if content.strip():
                            output_text = (output_text or "") + "\n" + content
                except Exception:
                    pass

    if output_text and output_text.strip():
        return output_text

    # Try running any solution Python files
    solution_files = []
    for root, dirs, files in os.walk('.'):
        dirs[:] = [d for d in dirs if not d.startswith('.') 
                   and d not in ['benchmark', '__pycache__', 'node_modules']]
        for f in files:
            if f.endswith('.py') and f not in ['eval.py', 'evaluate.py']:
                solution_files.append(os.path.join(root, f))

    for sol_file in solution_files:
        try:
            result = subprocess.run(
                [sys.executable, sol_file],
                capture_output=True,
                text=True,
                timeout=60,
                cwd='.'
            )
            combined = result.stdout + result.stderr
            if combined.strip():
                return combined
        except Exception:
            pass

    return output_text or ""


def check_solution_code():
    """Check if the solution code has the required components."""
    solution_files = []

    # Look in pred_results first
    for root, dirs, files in os.walk('pred_results'):
        for f in files:
            if f.endswith('.py'):
                solution_files.append(os.path.join(root, f))

    # Then look elsewhere
    if not solution_files:
        for root, dirs, files in os.walk('.'):
            dirs[:] = [d for d in dirs if not d.startswith('.') 
                       and d not in ['benchmark', '__pycache__']]
            for f in files:
                if f.endswith('.py') and f not in ['eval.py', 'evaluate.py']:
                    solution_files.append(os.path.join(root, f))

    for sol_file in solution_files:
        try:
            with open(sol_file, 'r') as <local-path>                code = f.read()

            checks = {
                'json_loading': bool(re.search(r'json\s*\.\s*load|json\.loads', code)),
                'file_path': bool(re.search(r'ffield\.json|I-ReaxFF', code)),
                'atom_parsing': bool(re.search(r'atom|mass', code, re.IGNORECASE)),
                'bond_parsing': bool(re.search(r'bond|rEquilibrium|Depi', code, re.IGNORECASE)),
                'validation': bool(re.search(r'warning|Warning|warn|valid', code, re.IGNORECASE)),
                'energy_calc': bool(re.search(r'energy|Energy', code, re.IGNORECASE)),
                'output': bool(re.search(r'print\s*\(', code)),
            }

            return checks, code
        except Exception:
            pass

    return {}, ""


def eval():
    """
    Evaluate the solution for ReaxFF force field parameter loading and validation.

    Checks:
    1. Force field parameters are loaded (atom types, bond types, etc.)
    2. Validation is performed with warnings for issues found
    3. Energy calculations are demonstrated
    4. Numerical values are reasonable
    """

    output_text = get_output_text()
    code_checks, code = check_solution_code()

    reasons_pass = []
    reasons_fail = []

    # =========================================================
    # PRIMARY: Check output content
    # =========================================================

    if output_text and output_text.strip():

        # Check 1: Parameter loading information
        # Look for any indication that parameters were loaded
        param_loading_patterns = [
            r'\d+\s*(?:unique\s*)?atom\s*type',
            r'atom\s*type[s]?\s*[:\-]\s*\d+',
            r'[Ll]oaded\s+\d+',
            r'[Ff]ound\s+\d+',
            r'atom\s*type[s]?.*?C\b',  # mentions C atom type
            r'\bC\b.*atom',
            r'bond\s*type',
            r'rEquilibrium',
            r'C-C|C-H|H-H',  # bond type names
        ]

        has_param_loading = any(re.search(p, output_text, re.IGNORECASE) 
                                for p in param_loading_patterns)

        if has_param_loading:
            reasons_pass.append("Parameter loading information present")
        else:
            reasons_fail.append("No parameter loading information found")

        # Check 2: Validation warnings or results
        validation_patterns = [
            r'[Ww]arning',
            r'[Vv]alidat',
            r'[Mm]issing\s+(?:Depi|parameter|bond)',
            r'[Nn]egative',
            r'[Oo]utside.*range',
            r'[Ii]ssue',
            r'[Nn]o\s+(?:angle|torsion)\s+parameters',
            r'[Bb]ond.*[Vv]alidat',
        ]

        has_validation = any(re.search(p, output_text, re.IGNORECASE) 
                             for p in validation_patterns)

        if has_validation:
            reasons_pass.append("Validation results/warnings present")
        else:
            reasons_fail.append("No validation results or warnings found")

        # Check 3: Energy calculation
        energy_patterns = [
            r'[Ee]nergy',
            r'[Ee]V\b',
            r'kcal',
            r'kJ',
        ]

        has_energy = any(re.search(p, output_text) for p in energy_patterns)

        if has_energy:
            reasons_pass.append("Energy calculation present")
        else:
            reasons_fail.append("No energy calculation found")

        # Check 4: Numerical values present
        numerical_values = re.findall(r'[-+]?\d+\.\d+', output_text)
        has_numerical = len(numerical_values) > 0

        if has_numerical:
            # Verify values are finite
            all_finite = True
            for val_str in numerical_values[:20]:
                try:
                    val = float(val_str)
                    if math.isnan(val) or math.isinf(val):
                        all_finite = False
                        break
                except ValueError:
                    pass

            if all_finite:
                reasons_pass.append(f"Numerical values present and finite ({len(numerical_values)} found)")
            else:
                reasons_fail.append("Non-finite numerical values found")
        else:
            reasons_fail.append("No numerical values in output")

        # Check 5: Bond energy calculation specifically
        bond_energy_patterns = [
            r'[Bb]ond.*[Ee]nergy',
            r'[Ee]nergy.*bond',
            r'[Cc]alculated.*energy',
            r'energy.*=.*[-+]?\d',
            r'[Ee]quilibrium.*length',
            r'r0|re\b',
        ]

        has_bond_energy = any(re.search(p, output_text, re.IGNORECASE) 
                              for p in bond_energy_patterns)

        if has_bond_energy:
            reasons_pass.append("Bond energy calculation with details present")
        else:
            # Not strictly required but good to have
            pass

        # Check 6: C-C bond (known to be in the dataset)
        has_cc = bool(re.search(r'C-C|CC\b', output_text))
        if has_cc:
            reasons_pass.append("C-C bond parameters referenced")

        # Check 7: Warnings about specific known issues
        # The dataset has bonds C-H, H-C, H-H, others with missing Depi
        has_specific_warnings = bool(re.search(
            r'C-H|H-C|H-H|[Mm]issing|Depi|[Oo]thers',
            output_text
        ))
        if has_specific_warnings:
            reasons_pass.append("Specific parameter issues identified")

        # Scoring
        core_checks = [
            has_param_loading,
            has_validation,
            has_energy,
            has_numerical,
        ]

        core_score = sum(core_checks)

        if core_score >= 3:
            msg = f"PASSED: {core_score}/4 core checks passed. "
            msg += "Passed: " + "; ".join(reasons_pass)
            if reasons_fail:
                msg += ". Minor issues: " + "; ".join(reasons_fail)
            return (True, msg)
        elif core_score >= 2:
            # Check if code quality makes up for it
            code_quality = sum(1 for v in code_checks.values() if v)
            if code_quality >= 5:
                msg = f"PASSED: Output score {core_score}/4 but code quality is good ({code_quality}/7 code checks). "
                msg += "Passed: " + "; ".join(reasons_pass)
                return (True, msg)
            else:
                msg = f"FAILED: Only {core_score}/4 core checks passed. "
                msg += "Failed: " + "; ".join(reasons_fail)
                return (False, msg)
        else:
            msg = f"FAILED: Only {core_score}/4 core checks passed. "
            msg += "Failed: " + "; ".join(reasons_fail)
            if reasons_pass:
                msg += ". Passed: " + "; ".join(reasons_pass)
            return (False, msg)

    # =========================================================
    # SECONDARY: Check code quality if no output available
    # =========================================================

    if code_checks:
        required_checks = ['json_loading', 'file_path', 'validation', 'energy_calc', 'output']
        passed_required = [c for c in required_checks if code_checks.get(c, False)]
        failed_required = [c for c in required_checks if not code_checks.get(c, False)]

        if len(passed_required) >= 4:
            return (True, f"Output not captured but solution code contains all required components: {', '.join(passed_required)}")
        elif len(passed_required) >= 3:
            return (True, f"Output not captured but solution code contains most required components: {', '.join(passed_required)}. Missing: {', '.join(failed_required)}")
        else:
            return (False, f"Output not captured and solution code missing required components. Has: {', '.join(passed_required)}. Missing: {', '.join(failed_required)}")

    return (False, "No output captured and no solution code found to evaluate")


if __name__ == "__main__":
    result, reason = eval()
    print(f"Result: {result}")
    print(f"Reason: {reason}")

