        return (False, f"Missing file: {pred_analysis_path}")
    if not os.path.exists(pred_params_path):
        return (False, f"Missing file: {pred_params_path}")

    # Step 2: Verify files are valid JSON
    try:
        with open(pred_analysis_path) as <local-path>            pred_analysis = json.load(f)
    except json.JSONDecodeError as <local-path>        return (False, f"Invalid JSON in analysis file: {e}")

