        with open(pred_params_path) as <local-path>            pred_params = json.load(f)
    except json.JSONDecodeError as <local-path>        return (False, f"Invalid JSON in params file: {e}")

    # Step 3: Check that analysis file has meaningful content
    if not isinstance(pred_analysis, dict) or len(pred_analysis) == 0:
        return (False, "Analysis file is empty or not a dictionary")

    if not isinstance(pred_params, dict) or len(pred_params) == 0:
        return (False, "Params file is empty or not a dictionary")

    # Step 4: Check for GP-related content in analysis file
    # Accept various naming conventions
    analysis_str = json.dumps(pred_analysis).lower()

    # Check for uncertainty/std information
    has_uncertainty = any(key in analysis_str for key in [
        'std', 'uncertainty', 'prediction_std', 'uncertainties'
    ])
    if not has_uncertainty:
        return (False, "Analysis file missing uncertainty/std information from GP predictions")

    # Check for score/performance metric
    has_score = any(key in analysis_str for key in [
        'score', 'rmse', 'r2', 'mse', 'error', 'accuracy'
    ])
    if not has_score:
        return (False, "Analysis file missing GP performance score/metric")

    # Check for bond statistics
    has_bond_stats = any(key in analysis_str for key in [
        'bond', 'length', 'distance', 'statistics', 'mean', 'std'
    ])
    if not has_bond_stats:
        return (False, "Analysis file missing bond statistics")

    # Step 5: Validate numerical values are reasonable
    def find_values_by_key_fragment(d, fragments, visited=None):
        """Recursively find all numeric values whose keys contain any fragment."""
        if visited is None:
            visited = set()
        results = {}
        if id(d) in visited:
            return results
        visited.add(id(d))

        if isinstance(d, dict):
            for k, v in d.items():
                k_lower = str(k).lower()
                if isinstance(v, (int, float)) and not isinstance(v, bool):
                    for frag in fragments:
                        if frag in k_lower:
                            results[k] = v
                elif isinstance(v, (dict, list)):
                    results.update(find_values_by_key_fragment(v, fragments, visited))
        elif isinstance(d, list):
            for item in <local-path>                if isinstance(item, (dict, list)):
                    results.update(find_values_by_key_fragment(item, fragments, visited))
        return results

    # Check uncertainty values are non-negative
    std_values = find_values_by_key_fragment(pred_analysis, ['std', 'uncertainty'])
    for key, val in std_values.items():
        if isinstance(val, (int, float)) and val < 0:
            return (False, f"Negative uncertainty value found: {key}={val}")

    # Step 6: Check params file has GP-related content
    params_str = json.dumps(pred_params).lower()
    has_kernel = any(key in params_str for key in [
        'kernel', 'rbf', 'length_scale', 'constant', 'gp', 'gaussian'
    ])
    has_training = any(key in params_str for key in [
        'training', 'train', 'data', 'lengths', 'orders', 'n_restarts', 'optimizer'
    ])

    if not has_kernel and not has_training:
        return (False, "Params file missing GP kernel or training information")

    # Step 7: Check that prediction uncertainties exist and are a list/array
    # Accept various key names for uncertainties
    uncertainty_data = None
    for key in pred_analysis:
        k_lower = key.lower()
        if any(frag in k_lower for frag in ['uncertainty', 'uncertainties', 'std', 'prediction_std']):
            val = pred_analysis[key]
            if isinstance(val, list):
                uncertainty_data = val
                break
            elif isinstance(val, dict):
                # Could be nested
                for subkey, subval in val.items():
                    if isinstance(subval, list) and len(subval) > 0:
                        uncertainty_data = subval
                        break

    if uncertainty_data is not None:
        # Validate the uncertainty values
        try:
            uncertainty_arr = np.array(uncertainty_data, dtype=float)
            if len(uncertainty_arr) == 0:
                return (False, "Prediction uncertainties list is empty")
            if np.any(uncertainty_arr < 0):
                return (False, "Some prediction uncertainties are negative")
            # Uncertainties should be finite
            if not np.all(np.isfinite(uncertainty_arr)):
                return (False, "Some prediction uncertainties are not finite (NaN or Inf)")
        except (ValueError, TypeError) as <local-path>            # If it's nested, that's okay - just check it exists
            pass

    # Step 8: Check bond statistics have reasonable values
