            if val < 0:
                return (False, f"Negative RMSE value: {key}={val}")
            if val > 10:
                return (False, f"Unreasonably large RMSE value: {key}={val} (expected < 10 for bond orders)")

    # Check RÂ² scores if present - should be between -1 and 1 (or at least not absurdly large)
    r2_values = find_values_by_key_fragment(pred_analysis, ['r2', 'score', 'r_squared'])
    for key, val in r2_values.items():
        if isinstance(val, (int, float)):
            if val > 1.01:  # Allow tiny floating point errors
                return (False, f"RÂ² score {key}={val} is greater than 1.0, which is invalid")

    # Step 9: Verify the analysis file structure has the key components mentioned in the task
    # The task requires: GP scores, prediction uncertainties, bond statistics
