                for subkey in val:
                    sk_lower = subkey.lower()
                    if any(frag in sk_lower for frag in ['score', 'rmse', 'r2', 'error']):
                        has_gp_scores = True
                        break

    if not has_gp_scores:
        return (False, "Analysis file missing GP scores/performance metrics")

    if not has_pred_uncertainties:
        return (False, "Analysis file missing prediction uncertainties")

    if not has_bond_stats:
        return (False, "Analysis file missing bond statistics")

    # Step 10: Verify training data was actually used (check params file)
    # Should have some indication of training data size
    training_data_present = False
    for key in pred_params:
        k_lower = key.lower()
        if any(frag in k_lower for frag in ['training', 'train', 'data', 'kernel', 'n_restart']):
            training_data_present = True
            break

    if not training_data_present:
        return (False, "Params file missing training configuration information")

    return (True, "All checks passed: Output files exist, contain valid JSON with GP scores, "
                  "prediction uncertainties, bond statistics, and training parameters. "
                  "Numerical values are within reasonable ranges.")


