    def load_csv(path):
        with open(path, "r") as <local-path>            reader = csv.reader(f)
            header = next(reader)
            rows = []
            for row in reader:
                rows.append([float(x) for x in row])
        return header, np.array(rows)

    try:
        pred_header, pred_data = load_csv(pred_csv)
